from collections import defaultdict
case = int(input())
for t in range(case):
	length = int(input())
	arr = list(map(int, input().split()))
	count = defaultdict(int)
	minim = -1
	for i in range(length):
		if arr[i] != -1:
			if arr[i] > i + 1 or arr[i] < minim:
				print(-1)
				break
			else:
				minim = arr[i]
				count[arr[i]] += 1
	else:
		smallest = 0
		ans = [None] * length
		i = 0
		next = -1
		while i < length:
			if next != -1:
				if next == smallest:
					smallest += 1
				ans[i] = next
				next = -1
				if arr[i] != -1:
					count[arr[i]] -= 1
					if count[arr[i]] == 0:
						next = arr[i]
				i += 1
			elif count[smallest] == 0:
				ans[i] = smallest
				if arr[i] != -1:
					count[arr[i]] -= 1
					if count[arr[i]] == 0:
						next = arr[i]
				i += 1
				smallest += 1
			else:
				smallest += 1
		print(' '.join(map(str, ans)))
